def countExpressions(num, target):
    n = len(num)

    def go(i, total, last):
        if i == n:
            return 1 if total == target else 0
        cnt = 0
        for j in range(i, n):
            if j > i and num[i] == "0":
                break
            v = int(num[i:j + 1])
            if i == 0:
                cnt += go(j + 1, v, v)
            else:
                cnt += go(j + 1, total + v, v)
                cnt += go(j + 1, total - v, -v)
                cnt += go(j + 1, total - last + last * v, last * v)
        return cnt

    return go(0, 0, 0)
